			NOT = { has_country_flag = extreme_frontiers_1531_end_dialog }
		}
		allow = {
			resource_stockpile_compare = {
				resource = energy
				value >= 3000
			}
		}
		response_text = extreme_frontiers.1531.f.reply
		is_dialog_only = yes
		ai_chance = { factor = 1 }
		if = {
			limit = { NOT = { has_country_flag = extreme_frontiers_1531_end_dialog } }
			set_country_flag = extreme_frontiers_1531_end_dialog
			set_country_flag = extreme_frontiers_1531_paid
		}
		add_resource = {
			energy = -3000
		}
	}

	option = {
		name = extreme_frontiers.1531.g # refuse (ends comms early)
		trigger = {
			has_country_flag = extreme_frontiers_1531_d
			NOT = { has_country_flag = extreme_frontiers_1531_end_dialog }
		}
		ai_chance = { factor = 1 }
		country_event = {
			id = extreme_frontiers.1532
			scopes = {
				from = from
			}
		}
	}

	## end comms ##
	option = { # paid
		name = extreme_frontiers.1531.h
		trigger = {
			has_country_flag = extreme_frontiers_1531_end_dialog
			has_country_flag = extreme_frontiers_1531_paid
		}
		ai_chance = { factor = 1 }
		country_event = {
			id = extreme_frontiers.1535
			scopes = {
				from = event_target:georadiation_undetonated_planet@root
			}
		}
	}

	option = { # battle
		name = extreme_frontiers.1531.i
		trigger = {
			has_country_flag = extreme_frontiers_1531_end_dialog
			has_country_flag = extreme_frontiers_1531_battle
		}
		ai_chance = { factor = 1 }
		country_event = {
			id = extreme_frontiers.1532
			scopes = {
				from = from
			}
		}
	}

	after = {
		hidden_effect = {
			remove_country_flag = extreme_frontiers_1531_a
			remove_country_flag = extreme_frontiers_1531_b
			remove_country_flag = extreme_frontiers_1531_c
			remove_country_flag = extreme_frontiers_1531_d
			remove_country_flag = extreme_frontiers_1531_end_dialog
			remove_country_flag = extreme_frontiers_1531_paid
			remove_country_flag = extreme_frontiers_1531_battle
		}
	}
}

